// embedded n8n/lib/agent_config.js (drift-proof; test asserts equality)
// agent_config.js — Stage 4 central configuration contract (B1).
//
// ONE place resolves the entire agent runtime config from environment variables + safe defaults,
// so the operator never hand-edits a Spreadsheet ID (or any limit/flag) inside individual nodes.
// The orchestrator calls resolveConfig() once and passes the resolved object downstream; every other
// workflow receives config from the request record instead of carrying its own copy.
//
// NO secrets live here or in workflow JSON. Credentials (Google/Telegram/Claude/Apify) stay in the
// n8n credential store; this module only resolves NON-secret runtime settings + the spreadsheet id
// (an id, not a secret) from $env. In a Code node call it as resolveConfig($env) — the harness shims
// $env as {} so the same code runs offline.

function str(v) { return v == null ? '' : String(v).trim(); }
function num(v, d) { const n = Number(v); return isFinite(n) && str(v) !== '' ? n : d; }
function bool(v, d) {
  if (v === true) return true;
  if (v === false) return false;
  const s = str(v).toLowerCase();
  if (s === 'true' || s === 'yes' || s === '1') return true;
  if (s === 'false' || s === 'no' || s === '0') return false;
  return d;
}
function list(v) { return str(v).split(/[\s,;]+/).filter(Boolean); }

// Production-safe defaults: fail-closed (approval + source-health required), website-only allowlist,
// LLM features OFF, tight budgets. Everything is overridable by env or explicit override.
const DEFAULTS = {
  spreadsheet_id: '',
  telegram_allowed_user_ids: [],
  max_sources_per_request: 3,
  max_items_per_source: 25,
  max_external_calls: 40,
  source_budget_usd: 0.20,
  llm_budget_usd: 0.50,
  default_region: 'Москва/МО',
  default_niche: 'credit_brokerage',
  source_allowlist: ['website'],
  require_approval: true,
  require_source_health: true,
  enable_llm_planner: false,
  enable_llm_summary: false,
  report_data_mode: 'live'
};

// Map env var -> resolved config. Unknown/blank env falls back to DEFAULTS; explicit overrides win last.
function resolveConfig(env, overrides) {
  env = env || {};
  overrides = overrides || {};
  const allowedUsers = list(env.MS_TELEGRAM_ALLOWED_USER_IDS);
  const allowlist = list(env.MS_SOURCE_ALLOWLIST).map(s => s.toLowerCase());
  const cfg = {
    spreadsheet_id: str(env.MS_SPREADSHEET_ID) || DEFAULTS.spreadsheet_id,
    telegram_allowed_user_ids: (allowedUsers.length ? allowedUsers : DEFAULTS.telegram_allowed_user_ids).map(String),
    max_sources_per_request: num(env.MS_MAX_SOURCES, DEFAULTS.max_sources_per_request),
    max_items_per_source: num(env.MS_MAX_ITEMS_PER_SOURCE, DEFAULTS.max_items_per_source),
    max_external_calls: num(env.MS_MAX_EXTERNAL_CALLS, DEFAULTS.max_external_calls),
    source_budget_usd: num(env.MS_SOURCE_BUDGET_USD, DEFAULTS.source_budget_usd),
    llm_budget_usd: num(env.MS_LLM_BUDGET_USD, DEFAULTS.llm_budget_usd),
    default_region: str(env.MS_DEFAULT_REGION) || DEFAULTS.default_region,
    default_niche: str(env.MS_DEFAULT_NICHE) || DEFAULTS.default_niche,
    source_allowlist: allowlist.length ? allowlist : DEFAULTS.source_allowlist.slice(),
    require_approval: bool(env.MS_REQUIRE_APPROVAL, DEFAULTS.require_approval),
    require_source_health: bool(env.MS_REQUIRE_SOURCE_HEALTH, DEFAULTS.require_source_health),
    enable_llm_planner: bool(env.MS_ENABLE_LLM_PLANNER, DEFAULTS.enable_llm_planner),
    enable_llm_summary: bool(env.MS_ENABLE_LLM_SUMMARY, DEFAULTS.enable_llm_summary),
    report_data_mode: str(env.MS_REPORT_DATA_MODE) || DEFAULTS.report_data_mode
  };
  for (const k in overrides) {
    if (Object.prototype.hasOwnProperty.call(overrides, k)) cfg[k] = overrides[k];
  }
  // completeness check the orchestrator surfaces in the execution summary — never starts paid work blind
  cfg.missing = [];
  if (!cfg.spreadsheet_id) cfg.missing.push('MS_SPREADSHEET_ID');
  if (!cfg.telegram_allowed_user_ids.length) cfg.missing.push('MS_TELEGRAM_ALLOWED_USER_IDS');
  cfg.config_complete = cfg.missing.length === 0;
  return cfg;
}

function isAllowedUser(cfg, userId) {
  return ((cfg && cfg.telegram_allowed_user_ids) || []).indexOf(String(userId)) >= 0;
}
function sourceAllowed(cfg, source) {
  return ((cfg && cfg.source_allowlist) || []).indexOf(String(source).toLowerCase()) >= 0;
}
// --- end embedded agent_config ---

// --- node driver ---
var __env=(typeof $env!=='undefined'&&$env)?$env:{};
return [{json:resolveConfig(__env)}];

// embedded n8n/lib/approval_gate.js (drift-proof; test asserts equality)
// approval_gate.js — Stage 4 approval & budget gate (B5).
//
// The single chokepoint every paid/external call passes through. It fails CLOSED: a call proceeds only
// when the request is approved, not cancelled, the source is allowlisted, item/call ceilings and the
// source + LLM budgets all hold, and this exact unit of work has not already been completed (idempotency
// key). A blocked gate returns a useful reason; it never throws and never leaks token values.

function str(v) { return v == null ? '' : String(v).trim(); }
function num(v, d) { const n = Number(v); return isFinite(n) ? n : d; }

const GATE_TERMINAL = ['completed', 'partial', 'failed', 'cancelled']; // local: avoids clash when co-embedded with agent_state.TERMINAL

// Deterministic idempotency key for one unit of external work (a source call within a request).
function idempotencyKey(agentRequestId, source, attempt) {
  return [str(agentRequestId) || 'req', str(source).toLowerCase() || 'src', 'a' + (num(attempt, 1))].join('::');
}

// ctx: { state, cancelled, approved, completed_keys:[], external_calls_made, source_spend_usd, llm_spend_usd }
// plan: { source, est_items, est_external_calls, est_source_cost_usd, est_llm_cost_usd }
// cfg:  resolved agent_config (limits + budgets + allowlist + require_approval)
function evaluateGate(plan, ctx, cfg) {
  plan = plan || {}; ctx = ctx || {}; cfg = cfg || {};
  const source = str(plan.source).toLowerCase();
  const key = idempotencyKey(ctx.agent_request_id || plan.agent_request_id, source, plan.attempt);
  const reasons = [];

  // 1. lifecycle: cancelled or terminal => hard stop
  if (ctx.cancelled === true || GATE_TERMINAL.indexOf(str(ctx.state)) >= 0) reasons.push('request_not_active');
  // 2. approval (when required)
  if (cfg.require_approval !== false && ctx.approved !== true) reasons.push('not_approved');
  // 3. source allowlist
  if ((cfg.source_allowlist || []).indexOf(source) < 0) reasons.push('source_not_allowed');
  // 4. idempotency: this unit already completed
  if ((ctx.completed_keys || []).indexOf(key) >= 0) reasons.push('already_completed');
  // 5. item ceiling
  if (num(plan.est_items, 0) > num(cfg.max_items_per_source, Infinity)) reasons.push('over_item_limit');
  // 6. external-call ceiling (cumulative)
  if (num(ctx.external_calls_made, 0) + num(plan.est_external_calls, 0) > num(cfg.max_external_calls, Infinity)) reasons.push('over_call_limit');
  // 7. source budget (cumulative)
  if (num(ctx.source_spend_usd, 0) + num(plan.est_source_cost_usd, 0) > num(cfg.source_budget_usd, Infinity)) reasons.push('over_source_budget');
  // 8. LLM budget (cumulative)
  if (num(ctx.llm_spend_usd, 0) + num(plan.est_llm_cost_usd, 0) > num(cfg.llm_budget_usd, Infinity)) reasons.push('over_llm_budget');

  return {
    allowed: reasons.length === 0,
    reason: reasons.join('; '),
    idempotency_key: key,
    source: source
  };
}
// --- end embedded approval_gate ---

// embedded n8n/lib/agent_state.js (drift-proof; test asserts equality)
// agent_state.js — Stage 4 durable request state machine (B4).
//
// A single request walks a fixed lifecycle. Transitions are validated (no skipping mandatory states),
// every transition is an event that is persisted (the orchestrator appends to agent_request_events),
// terminal states are absorbing, and — critically — no external/paid call may run once a request is
// cancelled or finished. Pure + deterministic; the orchestrator embeds a mirror of this.

const STATES = [
  'received', 'classified', 'awaiting_approval', 'approved', 'collecting', 'quality_check',
  'analyzing', 'aggregating', 'reporting', 'delivering', 'completed', 'partial', 'failed', 'cancelled'
];

const TERMINAL = ['completed', 'partial', 'failed', 'cancelled'];

// The mandatory happy-path order. quality_check/analyzing/aggregating/reporting/delivering may be
// collapsed into a terminal failure/cancel, but may not be skipped forward on the success path.
const NEXT = {
  received: ['classified', 'cancelled', 'failed'],
  classified: ['awaiting_approval', 'cancelled', 'failed'],
  awaiting_approval: ['approved', 'cancelled', 'failed'],
  approved: ['collecting', 'cancelled', 'failed'],
  collecting: ['quality_check', 'partial', 'cancelled', 'failed'],
  quality_check: ['analyzing', 'partial', 'cancelled', 'failed'],
  analyzing: ['aggregating', 'partial', 'cancelled', 'failed'],
  aggregating: ['reporting', 'partial', 'cancelled', 'failed'],
  reporting: ['delivering', 'partial', 'cancelled', 'failed'],
  delivering: ['completed', 'partial', 'failed'],
  completed: [], partial: [], failed: [], cancelled: []
};

function isTerminal(state) { return TERMINAL.indexOf(String(state)) >= 0; }

// Validate a single transition. cancelled is reachable from any non-terminal state (user /cancel).
function canTransition(from, to) {
  from = String(from); to = String(to);
  if (STATES.indexOf(from) < 0 || STATES.indexOf(to) < 0) return false;
  if (isTerminal(from)) return false;                 // terminal is absorbing
  if (to === 'cancelled') return true;                // user can cancel any live request
  return (NEXT[from] || []).indexOf(to) >= 0;
}

// Apply a transition, returning the new state record + the event to persist. Invalid transitions are
// rejected (state unchanged, ok=false) rather than throwing, so the orchestrator records a clear event.
function transition(record, to, meta) {
  record = record || {};
  const from = String(record.state || 'received');
  const ts = (meta && meta.ts) || '';
  if (!canTransition(from, to)) {
    return {
      ok: false, state: from,
      event: { agent_request_id: record.agent_request_id || '', from_state: from, to_state: String(to), accepted: false, reason: 'invalid_transition', ts: ts }
    };
  }
  const next = Object.assign({}, record, { state: to, prev_state: from });
  return {
    ok: true, state: to, record: next,
    event: { agent_request_id: record.agent_request_id || '', from_state: from, to_state: to, accepted: true, reason: (meta && meta.reason) || '', ts: ts }
  };
}

// Hard guard used by the approval/budget gate: once cancelled/terminal, NO external call may proceed.
function canMakeExternalCall(state) {
  const s = String(state);
  if (s === 'cancelled' || isTerminal(s)) return false;
  // external work only happens in the collection/analysis window after approval
  return ['approved', 'collecting', 'quality_check', 'analyzing', 'aggregating', 'reporting'].indexOf(s) >= 0;
}
// --- end embedded agent_state ---

// --- node driver ---
var cfg=$('Resolve Agent Config').first().json;
var req=($json&&$json.request)?$json.request:($json||{});
var plan=($json&&$json.plan)?$json.plan:{source:'website',est_items:cfg.max_items_per_source,est_external_calls:5,est_source_cost_usd:0.05,est_llm_cost_usd:0.10};
plan.source=plan.source||(plan.sources&&plan.sources[0])||'website';
var ctx={agent_request_id:req.agent_request_id||'req',state:req.state||'approved',approved:req.approved===true||req.state==='approved',cancelled:req.state==='cancelled'||req.cancelled===true,completed_keys:req.completed_keys||[],external_calls_made:0,source_spend_usd:0,llm_spend_usd:0};
var canCall=canMakeExternalCall(ctx.state);
var g=evaluateGate(plan,ctx,cfg);
var allowed=g.allowed&&canCall;
return [{json:{gate_allowed:allowed,gate_reason:allowed?'ok':(g.reason||'state_blocks_external_call'),idempotency_key:g.idempotency_key,plan:plan,request:req,cfg:cfg}}];

// embedded n8n/lib/source_adapter.js (drift-proof; test asserts equality)
// source_adapter.js — Stage 4 source adapter contract (B6).
//
// Every collector (website/Firecrawl WF04, Avito WF09, VK WF11, ...) is wrapped to return ONE canonical
// shape so the orchestrator never reaches into source-specific fields. normalizeAdapterResult() maps a
// raw collector summary onto the contract and decides the next orchestration state from the outcome.
// For the MVP the website family is first-class; Avito is an experimental search-card discovery adapter;
// VK is optional and its absence must not break the website E2E.

function str(v) { return v == null ? '' : String(v).trim(); }
function num(v, d) { const n = Number(v); return isFinite(n) ? n : (d === undefined ? 0 : d); }

const FAMILIES = {
  website: { family: 'website', platform: 'website', first_class: true },
  avito: { family: 'classifieds', platform: 'avito', first_class: false, experimental: true },
  vk: { family: 'social', platform: 'vk', first_class: false, optional: true }
};

// raw: a collector's live_source_runs-shaped summary (already produced by WF04/WF09/WF11).
// Returns the canonical adapter result + the orchestration state this outcome implies.
function normalizeAdapterResult(sourceKey, raw, ctx) {
  raw = raw || {}; ctx = ctx || {};
  const fam = FAMILIES[str(sourceKey).toLowerCase()] || { family: 'unknown', platform: str(sourceKey).toLowerCase(), first_class: false };
  const received = num(raw.items_received, num(raw.items_collected, 0));
  const written = num(raw.items_written, num(raw.records_written, received));
  const relevant = num(raw.items_relevant, 0);
  const quarantined = (str(raw.quality_status).toLowerCase() === 'quarantined') || raw.quarantined === true || str(raw.critical_flags) !== '';
  const errors = [].concat(raw.errors || []).map(str).filter(Boolean);
  if (raw.error) errors.unshift(str(raw.error));

  let next_state, status;
  if (quarantined) { status = 'quarantined'; next_state = 'quality_check'; }
  else if (errors.length && written === 0) { status = 'failed'; next_state = 'failed'; }
  else if (written === 0) { status = 'empty'; next_state = 'quality_check'; }
  else { status = 'ok'; next_state = 'quality_check'; }

  return {
    agent_request_id: str(raw.agent_request_id) || str(ctx.agent_request_id),
    source: str(sourceKey).toLowerCase(),
    source_family: fam.family,
    platform: str(raw.platform) || fam.platform,
    data_mode: str(raw.data_mode) || 'live',
    source_run_id: str(raw.source_run_id) || str(raw.run_id),
    workflow_run_id: str(raw.workflow_run_id),
    items_requested: num(raw.items_requested, num(ctx.requested, 0)),
    items_received: received,
    items_written: written,
    items_relevant: relevant,
    external_calls: num(raw.external_calls, num(raw.api_calls, 0)),
    cost_status: str(raw.cost_status) || 'unknown',      // never fake $0
    cost_usd: (raw.cost_usd === undefined || raw.cost_usd === null) ? null : num(raw.cost_usd, null),
    quarantined: quarantined,
    first_class: !!fam.first_class,
    experimental: !!fam.experimental,
    optional: !!fam.optional,
    status: status,
    errors: errors,
    next_state: next_state
  };
}

// Roll several adapter results into the request-level collection outcome: completed / partial / no_data.
function rollupCollection(results) {
  results = Array.isArray(results) ? results.filter(Boolean) : [];
  const ok = results.filter(r => r.status === 'ok');
  const failed = results.filter(r => r.status === 'failed');
  const quarantined = results.filter(r => r.quarantined);
  const written = results.reduce((a, r) => a + num(r.items_written, 0), 0);
  let outcome;
  if (results.length === 0) outcome = 'no_data';
  else if (ok.length === 0) outcome = 'no_data';               // all failed / empty / quarantined
  else if (failed.length || quarantined.length || ok.length < results.length) outcome = 'partial';
  else outcome = 'complete';
  return {
    outcome: outcome,
    sources_total: results.length,
    sources_ok: ok.length,
    sources_failed: failed.length,
    sources_quarantined: quarantined.length,
    items_written: written
  };
}
// --- end embedded source_adapter ---

// --- node driver ---
var g=$('Approval & Budget Gate').first().json;
var raw=($json&&$json.live_source_run)?$json.live_source_run:($json||{});
var res=normalizeAdapterResult('website',raw,{agent_request_id:g.request.agent_request_id});
return [{json:{adapter:res,plan:g.plan,request:g.request,cfg:g.cfg}}];

